/**
 * Compose the Orient moment for one activity from authoritative model + sequence data.
 *
 * @param {import("./types").LearnerActivity} modelActivity
 * @param {{ studyPhaseByActivityId: Object.<string,string>, purposeByActivityId: Object.<string,string> }} sequenceContext
 * @returns {import("./types").CompositionMoment|null}
 */
function composeOrientMoment(modelActivity, sequenceContext) {
  var activityId = String((modelActivity && modelActivity.id) || "").trim();
  if (!activityId) return null;

  var items = [];
  var studyPhase =
    sequenceContext &&
    sequenceContext.studyPhaseByActivityId &&
    sequenceContext.studyPhaseByActivityId[activityId];
  var activityPurpose =
    sequenceContext &&
    sequenceContext.purposeByActivityId &&
    sequenceContext.purposeByActivityId[activityId];

  pushTextItem(items, "studyPhase", studyPhase, sourceRef(activityId, {
    sourceField: "learning_sequence.study_flow.phase",
    sourcePath: "learning_sequence.study_flow"
  }));

  pushTextItem(items, "activityPurpose", activityPurpose, sourceRef(activityId, {
    sourceField: "learning_sequence.timeline.purpose",
    sourcePath: "learning_sequence.timeline"
  }));

  var bridgePrompt = findOrientationBridgePrompt(modelActivity);
  if (bridgePrompt && String(bridgePrompt.text || "").trim()) {
    items.push({
      kind: "prompt",
      prompt: {
        sourceField: "intellectual_coherence_bridge",
        text: String(bridgePrompt.text || "").trim()
      },
      sourceRef: sourceRef(activityId, {
        sourceField: "intellectual_coherence_bridge",
        beatFunction: "orientation"
      })
    });
  }

  pushTextItem(items, "activity_preamble", modelActivity.preamble, sourceRef(activityId, {
    sourceField: "activity_preamble"
  }));

  pushTextItem(
    items,
    "reasoning_orientation",
    modelActivity.reasoningOrientation,
    sourceRef(activityId, { sourceField: "reasoning_orientation" })
  );

  var entryPrompt = findOrientationEntryPrompt(modelActivity);
  if (entryPrompt && String(entryPrompt.text || "").trim()) {
    items.push({
      kind: "prompt",
      prompt: {
        sourceField: String(entryPrompt.sourceField || "self_explanation_prompt"),
        text: String(entryPrompt.text || "").trim()
      },
      sourceRef: sourceRef(activityId, {
        sourceField: String(entryPrompt.sourceField || "self_explanation_prompt"),
        beatFunction: "orientation"
      })
    });
  }

  if (!items.length) return null;

  return {
    kind: "orient",
    items: items
  };
}

/**
 * When Orient suppresses the orientation beat, absorb leftover orientation
 * instructions/materials that Learn/Do/Check did not already claim.
 *
 * @param {import("./types").CompositionMoment|null} orientMoment
 * @param {import("./types").LearnerActivity} modelActivity
 * @param {{ learnMoment?: *, doMoment?: *, checkMoment?: * }} otherMoments
 * @returns {import("./types").CompositionMoment|null}
 */
function absorbUnassignedOrientationBeatContent(orientMoment, modelActivity, otherMoments) {
  if (!orientMoment || !Array.isArray(orientMoment.items)) return orientMoment;

  var beat = findBeatByFunction(modelActivity, "orientation");
  if (!beat) return orientMoment;

  var activityId = String((modelActivity && modelActivity.id) || "").trim();
  var assignedMaterials = Object.create(null);
  var assignedSteps = Object.create(null);

  function noteMoment(moment) {
    if (!moment) return;
    (Array.isArray(moment.items) ? moment.items : []).forEach(function (item) {
      if (!item) return;
      if (item.kind === "material" && item.material && item.material.id) {
        assignedMaterials[String(item.material.id)] = true;
      }
      if (item.kind === "instruction" && item.instruction) {
        assignedSteps[String(item.instruction.sourceStepNumber)] = true;
      }
    });
    (Array.isArray(moment.materials) ? moment.materials : []).forEach(function (material) {
      if (material && material.id) assignedMaterials[String(material.id)] = true;
    });
    (Array.isArray(moment.taskSteps) ? moment.taskSteps : []).forEach(function (step) {
      assignedSteps[String(step.sourceStepNumber)] = true;
    });
    (Array.isArray(moment.explanatorySteps) ? moment.explanatorySteps : []).forEach(function (step) {
      assignedSteps[String(step.sourceStepNumber)] = true;
    });
  }

  noteMoment(orientMoment);
  noteMoment(otherMoments && otherMoments.learnMoment);
  noteMoment(otherMoments && otherMoments.doMoment);
  noteMoment(otherMoments && otherMoments.checkMoment);

  var items = orientMoment.items.slice();
  var materials = Array.isArray(orientMoment.materials) ? orientMoment.materials.slice() : [];
  var changed = false;

  (Array.isArray(beat.instructions) ? beat.instructions : []).forEach(function (instruction) {
    var stepKey = String(instruction && instruction.sourceStepNumber);
    if (!instruction || assignedSteps[stepKey]) return;
    if (!String(instruction.text || "").trim()) return;
    items.push({
      kind: "instruction",
      role: "orientation",
      instruction: {
        sourceStepNumber: instruction.sourceStepNumber,
        text: String(instruction.text || "").trim()
      },
      sourceRef: sourceRef(activityId, {
        sourceStepNumber: instruction.sourceStepNumber,
        beatFunction: "orientation"
      })
    });
    assignedSteps[stepKey] = true;
    changed = true;
  });

  (Array.isArray(beat.materials) ? beat.materials : []).forEach(function (material) {
    var materialId = String((material && material.id) || "");
    if (!materialId || assignedMaterials[materialId]) return;
    items.push({
      kind: "material",
      role: learnItemRoleForMaterial(material),
      material: material,
      reveal: null,
      tableWorkspace: shouldComposeTableWorkspaceMaterial(material),
      sourceRef: sourceRef(activityId, {
        materialId: materialId,
        beatFunction: "orientation"
      })
    });
    materials.push(material);
    assignedMaterials[materialId] = true;
    changed = true;
  });

  if (!changed) return orientMoment;

  return Object.assign({}, orientMoment, {
    items: items,
    materials: materials
  });
}

